using OracleSqlParser;
using Xunit;

namespace OracleSqlParser.Tests;

public class DdlShapeTests
{
    private const string SelDual = "(SelectStatement body=(QuerySpecification selectList=[(ExpressionSelectItem expression=1)] from=[(NamedTable name=[DUAL])]))";

    [Fact]
    public void CreateTable_ColumnsAndConstraints() =>
        Assert.Equal(
            "(CreateTableStatement name=[HR T] columns=[" +
            "(ColumnDefinition name=ID type=(DataType name=NUMBER arguments=[10]) constraints=[(TableConstraint kind=PrimaryKey)]) " +
            "(ColumnDefinition name=N type=(DataType name=VARCHAR2 arguments=[5]) default='x' constraints=[(TableConstraint kind=NotNull)])] " +
            "constraints=[(TableConstraint name=U kind=Unique columns=[N]) (TableConstraint name=CK kind=Check check=(> ID 0))])",
            Shape.Of("CREATE TABLE hr.t (id NUMBER(10) PRIMARY KEY, n VARCHAR2(5) DEFAULT 'x' NOT NULL, CONSTRAINT u UNIQUE (n), CONSTRAINT ck CHECK (id > 0))"));

    [Theory]
    [InlineData("CREATE TABLE t (id NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY (START WITH 1 INCREMENT BY 2 NOCACHE))",
        "(ColumnDefinition name=ID type=(DataType name=NUMBER) identity=(IdentityClause mode=ByDefault onNull options=[(SequenceOption name=START WITH value=1) (SequenceOption name=INCREMENT BY value=2) (SequenceOption name=NOCACHE)]))")]
    [InlineData("CREATE TABLE t (id NUMBER GENERATED ALWAYS AS IDENTITY)", "(ColumnDefinition name=ID type=(DataType name=NUMBER) identity=(IdentityClause mode=Always))")]
    [InlineData("CREATE TABLE t (v NUMBER GENERATED ALWAYS AS (id * 2) VIRTUAL)", "(ColumnDefinition name=V type=(DataType name=NUMBER) virtualExpression=(* ID 2))")]
    [InlineData("CREATE TABLE t (v AS (id + 1))", "(ColumnDefinition name=V virtualExpression=(+ ID 1))")]
    [InlineData("CREATE TABLE t (c VARCHAR2(10) INVISIBLE COLLATE binary_ci ENCRYPT USING 'AES256' NO SALT)",
        "(ColumnDefinition name=C type=(DataType name=VARCHAR2 arguments=[10]) visible=false collation=BINARY_CI encrypt=(EncryptClause algorithm='AES256' noSalt))")]
    [InlineData("CREATE TABLE t (c NUMBER DEFAULT ON NULL 5 NOT NULL)", "(ColumnDefinition name=C type=(DataType name=NUMBER) default=5 defaultOnNull constraints=[(TableConstraint kind=NotNull)])")]
    [InlineData("CREATE TABLE t (a NUMBER CONSTRAINT nn NOT NULL, b NUMBER REFERENCES o (x) ON DELETE CASCADE)", "(ColumnDefinition name=A type=(DataType name=NUMBER) constraints=[(TableConstraint name=NN kind=NotNull)])")]
    public void CreateTable_ColumnProperties(string sql, string expected) => Assert.Equal(expected, Shape.Of<ColumnDefinition>(sql));

    [Fact]
    public void CreateTable_InlineReference() =>
        Assert.Equal("(TableConstraint kind=ForeignKey refTable=[O] refColumns=[X] onDelete=Cascade)",
            Shape.Of<TableConstraint>("CREATE TABLE t (b NUMBER REFERENCES o (x) ON DELETE CASCADE)"));

    [Theory]
    [InlineData("CREATE TABLE t (a NUMBER, CONSTRAINT fk FOREIGN KEY (a) REFERENCES p (id) ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED ENABLE NOVALIDATE)",
        "(TableConstraint name=FK kind=ForeignKey columns=[A] refTable=[P] refColumns=[ID] onDelete=SetNull state=(ConstraintState deferrable=true initiallyDeferred=true enable=true validate=false))")]
    [InlineData("CREATE TABLE t (a NUMBER, UNIQUE (a) USING INDEX TABLESPACE idx NOT DEFERRABLE)",
        "(TableConstraint kind=Unique columns=[A] state=(ConstraintState deferrable=false usingIndex=(UsingIndexClause attributes=[(TablespaceAttribute name=IDX)])))")]
    [InlineData("CREATE TABLE t (a NUMBER, PRIMARY KEY (a) USING INDEX pk_idx RELY DISABLE)",
        "(TableConstraint kind=PrimaryKey columns=[A] state=(ConstraintState enable=false rely=true usingIndex=(UsingIndexClause indexName=[PK_IDX])))")]
    [InlineData("CREATE TABLE t (a NUMBER, PRIMARY KEY (a) USING INDEX (CREATE INDEX i ON t (a)) EXCEPTIONS INTO exc)",
        "(TableConstraint kind=PrimaryKey columns=[A] state=(ConstraintState usingIndex=(UsingIndexClause create=(CreateIndexStatement name=[I] table=[T] columns=[(IndexColumn expression=A)])) exceptionsInto=[EXC]))")]
    public void ConstraintStates(string sql, string expected) => Assert.Equal(expected, Shape.Of<TableConstraint>(sql));

    [Theory]
    [InlineData("CREATE GLOBAL TEMPORARY TABLE tmp (a NUMBER) ON COMMIT PRESERVE ROWS",
        "(CreateTableStatement globalTemporary name=[TMP] columns=[(ColumnDefinition name=A type=(DataType name=NUMBER))] onCommit=PreserveRows)")]
    [InlineData("CREATE PRIVATE TEMPORARY TABLE ora$ptt_x (a NUMBER) ON COMMIT DROP DEFINITION",
        "(CreateTableStatement privateTemporary name=[ORA$PTT_X] columns=[(ColumnDefinition name=A type=(DataType name=NUMBER))] onCommit=DropDefinition)")]
    [InlineData("CREATE TABLE IF NOT EXISTS t (a NUMBER)", "(CreateTableStatement ifNotExists name=[T] columns=[(ColumnDefinition name=A type=(DataType name=NUMBER))])")]
    [InlineData("CREATE TABLE t2 AS SELECT 1 FROM dual", "(CreateTableStatement name=[T2] asQuery=" + SelDual + ")")]
    [InlineData("CREATE TABLE t3 (a, b) AS SELECT 1, 2 FROM dual",
        "(CreateTableStatement name=[T3] columns=[(ColumnDefinition name=A) (ColumnDefinition name=B)] asQuery=(SelectStatement body=(QuerySpecification selectList=[(ExpressionSelectItem expression=1) (ExpressionSelectItem expression=2)] from=[(NamedTable name=[DUAL])])))")]
    [InlineData("CREATE TABLE t OF emp_type", "(CreateTableStatement name=[T] ofType=[EMP_TYPE])")]
    [InlineData("CREATE OR REPLACE IMMUTABLE BLOCKCHAIN TABLE t (a NUMBER)", "(CreateTableStatement orReplace immutable blockchain name=[T] columns=[(ColumnDefinition name=A type=(DataType name=NUMBER))])")]
    public void CreateTable_Forms(string sql, string expected) => Assert.Equal(expected, Shape.Of(sql));

    [Theory]
    [InlineData("CREATE TABLE t (a NUMBER) TABLESPACE users PCTFREE 10 LOGGING NOCOMPRESS PARALLEL 4 ENABLE ROW MOVEMENT STORAGE (INITIAL 64K NEXT 1M MAXEXTENTS UNLIMITED)",
        "[(TablespaceAttribute name=USERS) (NumericAttribute kind=PctFree value=10) (LoggingAttribute logging) (CompressAttribute) (ParallelAttribute degree=4) (RowMovementAttribute enabled) (StorageAttribute options=[(StorageOption name=INITIAL value=64K) (StorageOption name=NEXT value=1M) (StorageOption name=MAXEXTENTS value=UNLIMITED)])]")]
    [InlineData("CREATE TABLE t (a NUMBER) NOLOGGING COMPRESS 2 NOCACHE NOPARALLEL DISABLE ROW MOVEMENT",
        "[(LoggingAttribute) (CompressAttribute compress prefixLength=2) (CacheAttribute) (ParallelAttribute noParallel) (RowMovementAttribute)]")]
    [InlineData("CREATE TABLE t (a NUMBER) COMPRESS FOR OLTP",
        "[(CompressAttribute compress method=[(WordItem value=FOR) (WordItem value=OLTP)])]")]
    [InlineData("CREATE TABLE t (a NUMBER) ORGANIZATION HEAP", "[(OrganizationAttribute organization=Heap)]")]
    [InlineData("CREATE TABLE t (a NUMBER) ORGANIZATION EXTERNAL (TYPE oracle_loader)",
        "[(OrganizationAttribute organization=External details=[(GroupItem items=[(WordItem value=TYPE) (WordItem value=ORACLE_LOADER)])])]")]
    [InlineData("CREATE TABLE t (a NUMBER, c CLOB) LOB (c) STORE AS SECUREFILE (ENABLE STORAGE IN ROW) TABLESPACE users",
        "[(OtherAttribute items=[(WordItem value=LOB) (GroupItem items=[(WordItem value=C)]) (WordItem value=STORE) (WordItem value=AS) (WordItem value=SECUREFILE) (GroupItem items=[(WordItem value=ENABLE) (WordItem value=STORAGE) (WordItem value=IN) (WordItem value=ROW)])]) (TablespaceAttribute name=USERS)]")]
    public void PhysicalAttributes(string sql, string expected) =>
        Assert.Equal(expected, AstPrinter.Print(Shape.Parse(sql).Descendants().OfType<CreateTableStatement>().First().Attributes));

    [Theory]
    [InlineData("CREATE TABLE p (a NUMBER, b DATE) PARTITION BY RANGE (b) INTERVAL (NUMTOYMINTERVAL(1, 'MONTH')) (PARTITION p1 VALUES LESS THAN (DATE '2020-01-01') TABLESPACE t1, PARTITION pmax VALUES LESS THAN (MAXVALUE))",
        "[(PartitionByAttribute method=Range columns=[B] interval=(FunctionCall name=[NUMTOYMINTERVAL] arguments=[(Argument value=1) (Argument value='MONTH')]) partitions=[(PartitionDefinition name=P1 lessThan values=[DATE'2020-01-01'] attributes=[(TablespaceAttribute name=T1)]) (PartitionDefinition name=PMAX lessThan values=[MAXVALUE])])]")]
    [InlineData("CREATE TABLE p (c VARCHAR2(1)) PARTITION BY LIST (c) (PARTITION pa VALUES ('A', 'B'), PARTITION pd VALUES (DEFAULT))",
        "[(PartitionByAttribute method=List columns=[C] partitions=[(PartitionDefinition name=PA values=['A' 'B']) (PartitionDefinition name=PD valuesDefault)])]")]
    [InlineData("CREATE TABLE p (id NUMBER) PARTITION BY HASH (id) PARTITIONS 4", "[(PartitionByAttribute method=Hash columns=[ID] partitionCount=4)]")]
    [InlineData("CREATE TABLE p (a NUMBER, b NUMBER) PARTITION BY RANGE (a) SUBPARTITION BY HASH (b) (PARTITION p1 VALUES LESS THAN (10) (SUBPARTITION s1, SUBPARTITION s2))",
        "[(PartitionByAttribute method=Range columns=[A] partitions=[(PartitionDefinition name=P1 lessThan values=[10] subpartitions=[(PartitionDefinition name=S1) (PartitionDefinition name=S2)])] subpartitionMethod=Hash subpartitionColumns=[B])]")]
    [InlineData("CREATE TABLE c (id NUMBER NOT NULL) PARTITION BY REFERENCE (fk_p)", "[(PartitionByAttribute method=Reference referenceConstraint=FK_P)]")]
    [InlineData("CREATE TABLE s (a NUMBER) PARTITION BY SYSTEM PARTITIONS 2", "[(PartitionByAttribute method=System partitionCount=2)]")]
    public void Partitioning(string sql, string expected) =>
        Assert.Equal(expected, AstPrinter.Print(Shape.Parse(sql).Descendants().OfType<CreateTableStatement>().First().Attributes));

    [Theory]
    [InlineData("CREATE UNIQUE INDEX ix ON t (a DESC, UPPER(b)) TABLESPACE users ONLINE REVERSE",
        "(CreateIndexStatement unique name=[IX] table=[T] columns=[(IndexColumn expression=A descending) (IndexColumn expression=(FunctionCall name=[UPPER] arguments=[(Argument value=B)]))] online reverse attributes=[(TablespaceAttribute name=USERS)])")]
    [InlineData("CREATE INDEX ix ON t (c) INDEXTYPE IS ctxsys.context PARAMETERS ('sync (on commit)')",
        "(CreateIndexStatement name=[IX] table=[T] columns=[(IndexColumn expression=C)] indextype=[CTXSYS CONTEXT] indextypeParameters='sync (on commit)')")]
    [InlineData("CREATE BITMAP INDEX bx ON t (a) LOCAL INVISIBLE", "(CreateIndexStatement bitmap name=[BX] table=[T] columns=[(IndexColumn expression=A)] visible=false local)")]
    [InlineData("CREATE INDEX cx ON CLUSTER c", "(CreateIndexStatement name=[CX] cluster=[C])")]
    [InlineData("CREATE INDEX IF NOT EXISTS ix ON hr.t x (a) PARALLEL 2 NOLOGGING",
        "(CreateIndexStatement ifNotExists name=[IX] table=[HR T] tableAlias=X columns=[(IndexColumn expression=A)] attributes=[(ParallelAttribute degree=2) (LoggingAttribute)])")]
    public void Indexes(string sql, string expected) => Assert.Equal(expected, Shape.Of(sql));

    [Theory]
    [InlineData("CREATE OR REPLACE FORCE VIEW v (a, b) AS SELECT 1, 2 FROM dual WITH READ ONLY",
        "(CreateViewStatement orReplace force name=[V] columns=[A B] query=(SelectStatement body=(QuerySpecification selectList=[(ExpressionSelectItem expression=1) (ExpressionSelectItem expression=2)] from=[(NamedTable name=[DUAL])])) readOnly)")]
    [InlineData("CREATE VIEW v AS SELECT 1 FROM dual WITH CHECK OPTION CONSTRAINT c1", "(CreateViewStatement name=[V] query=" + SelDual + " checkOption checkOptionConstraint=C1)")]
    [InlineData("CREATE EDITIONING VIEW v BEQUEATH CURRENT_USER AS SELECT 1 FROM dual", "(CreateViewStatement editioning name=[V] bequeath=CurrentUser query=" + SelDual + ")")]
    [InlineData("CREATE MATERIALIZED VIEW mv TABLESPACE users BUILD IMMEDIATE REFRESH FAST ON COMMIT ENABLE QUERY REWRITE AS SELECT 1 FROM dual",
        "(CreateViewStatement materialized name=[MV] buildImmediate=true refresh=(RefreshClause method=Fast mode=OnCommit) queryRewrite=true attributes=[(TablespaceAttribute name=USERS)] query=" + SelDual + ")")]
    [InlineData("CREATE MATERIALIZED VIEW mv BUILD DEFERRED REFRESH COMPLETE START WITH SYSDATE NEXT SYSDATE + 1 WITH PRIMARY KEY DISABLE QUERY REWRITE AS SELECT 1 FROM dual",
        "(CreateViewStatement materialized name=[MV] buildImmediate=false refresh=(RefreshClause method=Complete startWith=SYSDATE next=(+ SYSDATE 1) withPrimaryKey) queryRewrite=false query=" + SelDual + ")")]
    [InlineData("CREATE MATERIALIZED VIEW mv NEVER REFRESH AS SELECT 1 FROM dual", "(CreateViewStatement materialized name=[MV] refresh=(RefreshClause method=Never) query=" + SelDual + ")")]
    public void Views(string sql, string expected) => Assert.Equal(expected, Shape.Of(sql));

    [Theory]
    [InlineData("CREATE SEQUENCE s START WITH 1 INCREMENT BY 2 MAXVALUE 1000 NOCACHE CYCLE",
        "(CreateSequenceStatement name=[S] options=[(SequenceOption name=START WITH value=1) (SequenceOption name=INCREMENT BY value=2) (SequenceOption name=MAXVALUE value=1000) (SequenceOption name=NOCACHE) (SequenceOption name=CYCLE)])")]
    [InlineData("CREATE SEQUENCE IF NOT EXISTS s MINVALUE -5 CACHE 20 SCALE EXTEND", "(CreateSequenceStatement ifNotExists name=[S] options=[(SequenceOption name=MINVALUE value=(- 5)) (SequenceOption name=CACHE value=20) (SequenceOption name=SCALE) (SequenceOption name=EXTEND)])")]
    [InlineData("CREATE OR REPLACE PUBLIC SYNONYM syn FOR hr.emp@link", "(CreateSynonymStatement orReplace public name=[SYN] target=[HR EMP] dbLink=[LINK])")]
    [InlineData("CREATE SYNONYM s FOR t", "(CreateSynonymStatement name=[S] target=[T])")]
    public void SequencesAndSynonyms(string sql, string expected) => Assert.Equal(expected, Shape.Of(sql));

    [Theory]
    [InlineData("DROP TABLE IF EXISTS t CASCADE CONSTRAINTS PURGE", "(DropStatement kind=Table ifExists name=[T] cascadeConstraints purge)")]
    [InlineData("DROP PUBLIC SYNONYM s", "(DropStatement kind=Synonym public name=[S])")]
    [InlineData("DROP MATERIALIZED VIEW LOG ON t", "(DropStatement kind=MaterializedViewLog onTable=[T])")]
    [InlineData("DROP PACKAGE BODY pkg", "(DropStatement kind=PackageBody name=[PKG])")]
    [InlineData("DROP TABLESPACE ts INCLUDING CONTENTS AND DATAFILES CASCADE CONSTRAINTS", "(DropStatement kind=Tablespace name=[TS] cascadeConstraints includingContents andDatafiles)")]
    [InlineData("DROP TYPE t FORCE", "(DropStatement kind=Type name=[T] force)")]
    [InlineData("DROP USER u CASCADE", "(DropStatement kind=User name=[U] cascade)")]
    [InlineData("DROP DATABASE LINK l", "(DropStatement kind=DatabaseLink name=[L])")]
    [InlineData("DROP INDEX ix ONLINE", "(DropStatement kind=Index name=[IX] rest=[(WordItem value=ONLINE)])")]
    public void Drops(string sql, string expected) => Assert.Equal(expected, Shape.Of(sql));

    [Theory]
    [InlineData("ALTER TABLE t ADD (c NUMBER, d DATE DEFAULT SYSDATE, CONSTRAINT u UNIQUE (c))",
        "(AlterTableStatement name=[T] actions=[(AlterTableAction kind=AddColumns columns=[(ColumnDefinition name=C type=(DataType name=NUMBER)) (ColumnDefinition name=D type=(DataType name=DATE) default=SYSDATE)] constraints=[(TableConstraint name=U kind=Unique columns=[C])])])")]
    [InlineData("ALTER TABLE t ADD c NUMBER", "(AlterTableStatement name=[T] actions=[(AlterTableAction kind=AddColumns columns=[(ColumnDefinition name=C type=(DataType name=NUMBER))])])")]
    [InlineData("ALTER TABLE t ADD CONSTRAINT pk PRIMARY KEY (id)", "(AlterTableStatement name=[T] actions=[(AlterTableAction kind=AddConstraint constraints=[(TableConstraint name=PK kind=PrimaryKey columns=[ID])])])")]
    [InlineData("ALTER TABLE t MODIFY (c VARCHAR2(100) NOT NULL)", "(AlterTableStatement name=[T] actions=[(AlterTableAction kind=ModifyColumns columns=[(ColumnDefinition name=C type=(DataType name=VARCHAR2 arguments=[100]) constraints=[(TableConstraint kind=NotNull)])])])")]
    [InlineData("ALTER TABLE t MODIFY CONSTRAINT pk DISABLE", "(AlterTableStatement name=[T] actions=[(AlterTableAction kind=ModifyConstraint constraints=[(TableConstraint name=PK state=(ConstraintState enable=false))])])")]
    [InlineData("ALTER TABLE t DROP COLUMN c CASCADE CONSTRAINTS", "(AlterTableStatement name=[T] actions=[(AlterTableAction kind=DropColumns names=[C] cascade)])")]
    [InlineData("ALTER TABLE t DROP (a, b)", "(AlterTableStatement name=[T] actions=[(AlterTableAction kind=DropColumns names=[A B])])")]
    [InlineData("ALTER TABLE t DROP CONSTRAINT pk CASCADE", "(AlterTableStatement name=[T] actions=[(AlterTableAction kind=DropConstraint names=[PK] cascade)])")]
    [InlineData("ALTER TABLE t DROP PRIMARY KEY CASCADE", "(AlterTableStatement name=[T] actions=[(AlterTableAction kind=DropPrimaryKey cascade)])")]
    [InlineData("ALTER TABLE t DROP UNIQUE (a, b)", "(AlterTableStatement name=[T] actions=[(AlterTableAction kind=DropUnique names=[A B])])")]
    [InlineData("ALTER TABLE t SET UNUSED COLUMN c", "(AlterTableStatement name=[T] actions=[(AlterTableAction kind=SetUnused names=[C])])")]
    [InlineData("ALTER TABLE t RENAME COLUMN a TO b", "(AlterTableStatement name=[T] actions=[(AlterTableAction kind=RenameColumn names=[A] newName=B)])")]
    [InlineData("ALTER TABLE t RENAME CONSTRAINT a TO b", "(AlterTableStatement name=[T] actions=[(AlterTableAction kind=RenameConstraint names=[A] newName=B)])")]
    [InlineData("ALTER TABLE t RENAME TO t_old", "(AlterTableStatement name=[T] actions=[(AlterTableAction kind=RenameTo newName=T_OLD)])")]
    [InlineData("ALTER TABLE t ENABLE ROW MOVEMENT", "(AlterTableStatement name=[T] actions=[(AlterTableAction kind=Attributes attributes=[(RowMovementAttribute enabled)])])")]
    [InlineData("ALTER TABLE t PCTFREE 5 NOLOGGING", "(AlterTableStatement name=[T] actions=[(AlterTableAction kind=Attributes attributes=[(NumericAttribute kind=PctFree value=5) (LoggingAttribute)])])")]
    [InlineData("ALTER TABLE t ADD PARTITION p3 VALUES LESS THAN (30)",
        "(AlterTableStatement name=[T] actions=[(AlterTableAction kind=Other syntax=[(WordItem value=ADD) (WordItem value=PARTITION) (WordItem value=P3) (WordItem value=VALUES) (WordItem value=LESS) (WordItem value=THAN) (GroupItem items=[(LiteralItem kind=Number value=30)])])])")]
    [InlineData("ALTER TABLE IF EXISTS t ADD c NUMBER MODIFY d DATE DROP COLUMN e",
        "(AlterTableStatement name=[T] ifExists actions=[(AlterTableAction kind=AddColumns columns=[(ColumnDefinition name=C type=(DataType name=NUMBER))]) (AlterTableAction kind=ModifyColumns columns=[(ColumnDefinition name=D type=(DataType name=DATE))]) (AlterTableAction kind=DropColumns names=[E])])")]
    public void AlterTable(string sql, string expected) => Assert.Equal(expected, Shape.Of(sql));

    [Theory]
    [InlineData("CREATE USER bob IDENTIFIED BY pw", "(CreateUserStatement name=BOB clauses=[(UserClause kind=IdentifiedBy password=PW)])")]
    [InlineData("CREATE ROLE r", "(CreateRoleStatement name=R)")]
    [InlineData("CREATE DATABASE LINK l CONNECT TO u IDENTIFIED BY p USING 'tns'",
        "(CreateObjectStatement kind=DatabaseLink name=[L] body=[(WordItem value=CONNECT) (WordItem value=TO) (WordItem value=U) (WordItem value=IDENTIFIED) (WordItem value=BY) (WordItem value=P) (WordItem value=USING) (LiteralItem kind=String value=tns)])")]
    [InlineData("CREATE OR REPLACE PUBLIC DATABASE LINK l USING 'x'", "(CreateObjectStatement kind=DatabaseLink orReplace public name=[L] body=[(WordItem value=USING) (LiteralItem kind=String value=x)])")]
    [InlineData("CREATE DIRECTORY d AS '/tmp'", "(CreateObjectStatement kind=Directory name=[D] body=[(WordItem value=AS) (LiteralItem kind=String value=/tmp)])")]
    [InlineData("CREATE TABLESPACE ts DATAFILE 'f.dbf' SIZE 10M", "(CreateObjectStatement kind=Tablespace name=[TS] body=[(WordItem value=DATAFILE) (LiteralItem kind=String value=f.dbf) (WordItem value=SIZE) (LiteralItem kind=Number value=10M)])")]
    [InlineData("CREATE DOMAIN d AS NUMBER(3)", "(CreateObjectStatement kind=Domain name=[D] body=[(WordItem value=AS) (WordItem value=NUMBER) (GroupItem items=[(LiteralItem kind=Number value=3)])])")]
    [InlineData("CREATE PROPERTY GRAPH g VERTEX TABLES (v)", "(CreateObjectStatement kind=PropertyGraph name=[G] body=[(WordItem value=VERTEX) (WordItem value=TABLES) (GroupItem items=[(WordItem value=V)])])")]
    [InlineData("CREATE JSON RELATIONAL DUALITY VIEW dv AS SELECT 1", "(CreateObjectStatement kind=JsonRelationalDualityView name=[DV] body=[(WordItem value=AS) (WordItem value=SELECT) (LiteralItem kind=Number value=1)])")]
    [InlineData("CREATE MATERIALIZED VIEW LOG ON t WITH PRIMARY KEY", "(CreateObjectStatement kind=MaterializedViewLog body=[(WordItem value=ON) (WordItem value=T) (WordItem value=WITH) (WordItem value=PRIMARY) (WordItem value=KEY)])")]
    [InlineData("ALTER SYSTEM FLUSH SHARED_POOL", "(AlterObjectStatement kind=System body=[(WordItem value=FLUSH) (WordItem value=SHARED_POOL)])")]
    [InlineData("ALTER INDEX ix REBUILD", "(AlterObjectStatement kind=Index name=[IX] body=[(WordItem value=REBUILD)])")]
    [InlineData("ALTER PROCEDURE p COMPILE", "(AlterObjectStatement kind=Procedure name=[P] body=[(WordItem value=COMPILE)])")]
    [InlineData("ALTER SEQUENCE s INCREMENT BY 5", "(AlterObjectStatement kind=Sequence name=[S] body=[(WordItem value=INCREMENT) (WordItem value=BY) (LiteralItem kind=Number value=5)])")]
    public void GenericObjectDdl(string sql, string expected) => Assert.Equal(expected, Shape.Of(sql));

    [Theory]
    [InlineData("CREATE USER IF NOT EXISTS app IDENTIFIED BY \"Pw 1\" DEFAULT TABLESPACE users TEMPORARY TABLESPACE temp QUOTA UNLIMITED ON users PROFILE p PASSWORD EXPIRE ACCOUNT UNLOCK CONTAINER = ALL",
        "(CreateUserStatement ifNotExists name=APP clauses=[(UserClause kind=IdentifiedBy password=\"Pw 1\") (UserClause kind=DefaultTablespace tablespace=USERS) (UserClause kind=TemporaryTablespace tablespace=TEMP) (UserClause kind=Quota tablespace=USERS unlimited) (UserClause kind=Profile profile=P) (UserClause kind=PasswordExpire) (UserClause kind=AccountUnlock) (UserClause kind=Container container=All)])")]
    [InlineData("ALTER USER u IDENTIFIED BY pw QUOTA 100M ON data DEFAULT ROLE r1, r2 ENABLE EDITIONS FORCE",
        "(AlterUserStatement name=U clauses=[(UserClause kind=IdentifiedBy password=PW) (UserClause kind=Quota tablespace=DATA quota=100M) (UserClause kind=DefaultRole roleSet=Roles roles=[R1 R2]) (UserClause kind=EnableEditions force)])")]
    [InlineData("ALTER USER u DEFAULT ROLE ALL EXCEPT r1 TEMPORARY TABLESPACE temp",
        "(AlterUserStatement name=U clauses=[(UserClause kind=DefaultRole roleSet=All exceptRoles=[R1]) (UserClause kind=TemporaryTablespace tablespace=TEMP)])")]
    [InlineData("ALTER USER u GRANT CONNECT THROUGH sh WITH ROLE warehouse_user AUTHENTICATION REQUIRED",
        "(AlterUserStatement name=U clauses=[(UserClause kind=GrantConnectThrough proxy=SH roleSet=Roles roles=[WAREHOUSE_USER] authenticationRequired)])")]
    [InlineData("ALTER USER u GRANT CONNECT THROUGH sh WITH NO ROLES",
        "(AlterUserStatement name=U clauses=[(UserClause kind=GrantConnectThrough proxy=SH roleSet=None)])")]
    [InlineData("ALTER USER u REVOKE CONNECT THROUGH ENTERPRISE USERS",
        "(AlterUserStatement name=U clauses=[(UserClause kind=RevokeConnectThrough enterpriseUsers)])")]
    [InlineData("CREATE USER x IDENTIFIED EXTERNALLY AS 'CN=x'",
        "(CreateUserStatement name=X clauses=[(UserClause kind=IdentifiedExternally externalName='CN=x')])")]
    [InlineData("ALTER USER u ACCOUNT LOCK", "(AlterUserStatement name=U clauses=[(UserClause kind=AccountLock)])")]
    [InlineData("ALTER USER u READ ONLY", "(AlterUserStatement name=U clauses=[(UserClause kind=ReadOnly)])")]
    public void CreateAlterUser(string sql, string expected) => Assert.Equal(expected, Shape.Of(sql));

    [Theory]
    [InlineData("CREATE ROLE IF NOT EXISTS r NOT IDENTIFIED CONTAINER = ALL", "(CreateRoleStatement ifNotExists name=R authentication=NotIdentified container=All)")]
    [InlineData("CREATE ROLE r IDENTIFIED BY \"Pw\"", "(CreateRoleStatement name=R authentication=Password password=\"Pw\")")]
    [InlineData("ALTER ROLE r IDENTIFIED USING sec.pkg", "(AlterRoleStatement name=R authentication=Package package=[SEC PKG])")]
    [InlineData("ALTER ROLE r IDENTIFIED EXTERNALLY", "(AlterRoleStatement name=R authentication=External)")]
    [InlineData("ALTER ROLE r IDENTIFIED GLOBALLY CONTAINER = CURRENT", "(AlterRoleStatement name=R authentication=Global container=Current)")]
    public void CreateAlterRole(string sql, string expected) => Assert.Equal(expected, Shape.Of(sql));

    [Fact]
    public void CreateJava_Source()
    {
        var sql = "CREATE OR REPLACE AND COMPILE JAVA SOURCE NAMED \"Hello\" AS\npublic class Hello {\n  public static String hi() { return \"it's; fine\"; }\n}\n/\nSELECT 1 FROM dual;";
        var s = Shape.Parse(sql);
        Assert.Equal(2, s.Statements.Count);
        Assert.Equal(
            "(CreateJavaStatement orReplace andCompile kind=Source name=[\"Hello\"] sourceText=public class Hello {\n  public static String hi() { return \"it's; fine\"; }\n})",
            AstPrinter.Print(s.Statements[0]));
    }

    [Theory]
    [InlineData("CREATE OR REPLACE JAVA CLASS USING BFILE (dir, 'X.class')", "x")]
    public void CreateJava_RequiresNamed(string sql, string _) => Assert.False(SqlParser.Parse(sql).Success);

    [Theory]
    [InlineData("CREATE JAVA RESOURCE NAMED r USING BFILE (dir, 'f.txt')", "(CreateJavaStatement kind=Resource name=[R] usingKind=Bfile usingDirectory=DIR usingFile='f.txt')")]
    [InlineData("CREATE JAVA CLASS NAMED c USING BLOB SELECT b FROM t", "(CreateJavaStatement kind=Class name=[C] usingKind=Blob usingQuery=(SelectStatement body=(QuerySpecification selectList=[(ExpressionSelectItem expression=B)] from=[(NamedTable name=[T])])))")]
    [InlineData("CREATE JAVA SOURCE NAMED s RESOLVER ((* sys)) USING 'key'", "(CreateJavaStatement kind=Source name=[S] resolver=[(GroupItem items=[(GroupItem items=[(SymbolItem symbol=*) (WordItem value=SYS)])])] usingKind=Key usingKey='key')")]
    public void CreateJava_Other(string sql, string expected) => Assert.Equal(expected, Shape.Of(sql));

    [Theory]
    [InlineData("CREATE OR REPLACE LIBRARY l AS '/lib/x.so' AGENT 'ag'", "(CreateLibraryStatement orReplace name=[L] path='/lib/x.so' agent='ag')")]
    [InlineData("CREATE LIBRARY l IS 'x' CREDENTIAL cred", "(CreateLibraryStatement name=[L] path='x' credential=CRED)")]
    public void CreateLibrary(string sql, string expected) => Assert.Equal(expected, Shape.Of(sql));
}
